// cmdRouteStatus reports the routing engine's eligible-candidate trace for a
// requested intent (per ADR-005 §5). It calls service.ResolveRoute rather than
// enumerating route tables; score components and filter reasons come from the
// engine itself, not a parallel CLI implementation.
func cmdRouteStatus(workDir string, args []string) int {
	fs := flag.NewFlagSet("route-status", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	profile := fs.String("profile", "", "Routing profile (named power shortcut; use --min-power / --max-power for exact bounds)")
	model := fs.String("model", "", "Pin a specific model")
	modelRef := fs.String("model-ref", "", "Model catalog reference (alias, profile, or canonical target; deprecated targets fail with replacement guidance)")
	provider := fs.String("provider", "", "Pin a specific provider")
	harness := fs.String("harness", "", "Pin a specific harness")
	minPower := fs.Int("min-power", 0, "Minimum catalog model power for automatic routing")
	maxPower := fs.Int("max-power", 0, "Maximum catalog model power for automatic routing")
	jsonOut := fs.Bool("json", false, "Output JSON")
	overrides := fs.Bool("overrides", false, "Print override_class_breakdown over a time window (ADR-006). "+
		"Operator-driven feedback loop; automatic learning is a future ADR. "+
		"Buckets with high override count and high outcome success rate suggest auto-routing is "+
		"picking suboptimally for that prompt class. Buckets with high override count and low "+
		"outcome success rate suggest users are pinning out of habit; consider UI nudges.")
	since := fs.String("since", "", "Time window for --overrides mode (Go duration, e.g. 24h, 168h). Default 7d (168h).")
	axis := fs.String("axis", "", "With --overrides, filter breakdown rows to overrides on this axis (harness|provider|model).")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	if *overrides {
		return cmdRouteStatusOverrides(workDir, *since, *axis, *jsonOut)
	}
	if err := rootfizeau.ValidatePowerBounds(*minPower, *maxPower); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 2
	}

	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
		ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
		SessionLogDir: sessionLogDir(workDir, cfg),
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	decision, resolveErr := svc.ResolveRoute(ctx, rootfizeau.RouteRequest{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
	})

	out := routeStatusOutput{
		Profile:  *profile,
		Model:    *model,
		ModelRef: *modelRef,
		Provider: *provider,
		Harness:  *harness,
		MinPower: *minPower,
		MaxPower: *maxPower,
		PowerPolicy: routeStatusPowerPolicy{
			Profile:  *profile,
			MinPower: *minPower,
			MaxPower: *maxPower,
		},
		Candidates: []routeStatusCandidate{},
	}
	if resolveErr != nil {
		out.Error = resolveErr.Error()
	}
	if decision != nil {
		out.SelectedEndpoint = decision.Endpoint
		out.Sticky = decision.Sticky
		out.Utilization = decision.Utilization
		out.PowerPolicy = routeStatusPowerPolicy{
			Profile:  decision.PowerPolicy.Profile,
			MinPower: decision.PowerPolicy.MinPower,
			MaxPower: decision.PowerPolicy.MaxPower,
		}
		winnerSet := decision.Harness != "" || decision.Provider != "" || decision.Model != ""
		for _, c := range decision.Candidates {
			entry := routeStatusCandidate{
				Harness:       c.Harness,
				Provider:      c.Provider,
				Endpoint:      c.Endpoint,
				Model:         c.Model,
				Score:         c.Score,
				ContextLength: c.ContextLength,
				ContextSource: c.ContextSource,
				Eligible:      c.Eligible,
				FilterReason:  c.FilterReason,
				Reason:        c.Reason,
				CostSource:    c.CostSource,
				Utilization:   c.Utilization,
				Components: routeStatusComponents{
					Power:            c.Components.Power,
					Cost:             c.Components.Cost,
					CostClass:        c.Components.CostClass,
					LatencyMS:        c.Components.LatencyMS,
					SpeedTPS:         c.Components.SpeedTPS,
					SuccessRate:      c.Components.SuccessRate,
					QuotaOK:          c.Components.QuotaOK,
					QuotaPercentUsed: c.Components.QuotaPercentUsed,
					QuotaTrend:       c.Components.QuotaTrend,
					Capability:       c.Components.Capability,
					ContextHeadroom:  c.Components.ContextHeadroom,
				},
			}
			if winnerSet && out.Winner == nil &&
				c.Harness == decision.Harness &&
				c.Provider == decision.Provider &&
				c.Model == decision.Model {
				entry.Winner = true
				w := entry
				out.Winner = &w
			}
			out.Candidates = append(out.Candidates, entry)
		}
	}

	if *jsonOut {
		data, _ := json.MarshalIndent(out, "", "  ")
		fmt.Println(string(data))
		if resolveErr != nil && (decision == nil || decision.Harness == "") {
			return 1
		}
		return 0
	}

	if out.Profile != "" {
		fmt.Printf("Profile: %s\n", out.Profile)
	}
	if out.PowerPolicy.Profile != "" || out.PowerPolicy.MinPower > 0 || out.PowerPolicy.MaxPower > 0 {
		fmt.Printf("Power policy: profile=%s", labelOrUnknown(out.PowerPolicy.Profile))
		if out.PowerPolicy.MinPower > 0 {
			fmt.Printf(" min=%d", out.PowerPolicy.MinPower)
		}
		if out.PowerPolicy.MaxPower > 0 {
			fmt.Printf(" max=%d", out.PowerPolicy.MaxPower)
		}
		fmt.Println()
	}
	if out.Model != "" {
		fmt.Printf("Model: %s\n", out.Model)
	}
	if out.ModelRef != "" {
		fmt.Printf("Model Ref: %s\n", out.ModelRef)
	}
	if out.MinPower > 0 {
		fmt.Printf("Min Power: %d\n", out.MinPower)
	}
	if out.MaxPower > 0 {
		fmt.Printf("Max Power: %d\n", out.MaxPower)
	}
	if out.Winner != nil {
		fmt.Printf("Winner: %s/%s/%s endpoint=%s score=%.2f\n", out.Winner.Harness, out.Winner.Provider, out.Winner.Model, out.Winner.Endpoint, out.Winner.Score)
	}
	if out.SelectedEndpoint != "" {
		fmt.Printf("Selected endpoint: %s\n", out.SelectedEndpoint)
	}

---
		return selection, p, pc, nil
	}

	// Direct provider selection or exact model pin.
	if providerName == "" {
		providerName = cfg.DefaultName()
	}
	p, pc, resolved, err := cfg.BuildProviderWithOverrides(providerName, overrides)
	if err != nil {
		return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
	}
	selection := providerSelection{
		Route:             providerName,
		Provider:          providerName,
		RequestedModel:    overrides.Model,
		RequestedModelRef: overrides.ModelRef,
		ResolvedModel:     pc.Model,
	}
	if resolved != nil {
		selection.ResolvedModelRef = resolved.CanonicalID
		selection.ReasoningDefault = fizeau.Reasoning(resolved.SurfacePolicy.ReasoningDefault)
		if resolved.ConcreteModel != "" {
			selection.ResolvedModel = resolved.ConcreteModel
		}
	}
	return selection, p, pc, nil
}

func resolveRouteTarget(cfg *agentConfig.Config, backendName, providerName string, overrides agentConfig.ProviderOverrides) (routeKey string, routeModelRef string, legacyBackend string, err error) {
	if providerName != "" {
		return "", "", "", nil
	}
	if backendName != "" {
		return "", "", backendName, nil
	}
	if overrides.Model != "" {
		return overrides.Model, "", "", nil
	}
	if overrides.ModelRef != "" {
		resolved, err := resolveCanonicalModelRef(cfg, overrides.ModelRef, overrides.AllowDeprecated)
		if err != nil {
			return "", "", "", err
		}
		return resolved.CanonicalID, overrides.ModelRef, "", nil
	}
	if cfg.Routing.DefaultModel != "" {
		return cfg.Routing.DefaultModel, "", "", nil
	}
	if cfg.Routing.DefaultModelRef != "" {
		resolved, err := resolveCanonicalModelRef(cfg, cfg.Routing.DefaultModelRef, true)
		if err != nil {
			return "", "", "", err
		}
		return resolved.CanonicalID, cfg.Routing.DefaultModelRef, "", nil
	}
	if cfg.DefaultBackend != "" {
		return "", "", cfg.DefaultBackend, nil
	}
	return "", "", "", nil
}

func buildRouteSelection(cfg *agentConfig.Config, workDir, routeKey, routeModelRef string, allowDeprecated bool) (providerSelection, any, agentConfig.ProviderConfig, error) {
	plan, err := buildSmartRoutePlan(cfg, workDir, routeKey, routeModelRef, allowDeprecated, nil, nil)
	if err != nil {
		return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
	}
	if len(plan.Order) == 0 {
		return providerSelection{}, nil, agentConfig.ProviderConfig{}, fmt.Errorf("config: no route candidates available for %q", routeKey)
	}
	selected := plan.Candidates[plan.Order[0]]
	if routeModelRef != "" && (selected.Model == "" || selected.Model == routeKey) {
		resolvedPC, _, err := cfg.ResolveProviderConfig(selected.Provider, agentConfig.ProviderOverrides{ModelRef: routeModelRef, AllowDeprecated: allowDeprecated})
		if err != nil {
			return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
		}
		selected.Model = resolvedPC.Model
	}
	p, pc, resolved, err := cfg.BuildProviderWithOverrides(selected.Provider, agentConfig.ProviderOverrides{
		Model:           selected.Model,
		ModelRef:        routeModelRef,
		AllowDeprecated: allowDeprecated,
	})
	if err != nil {
		return providerSelection{}, nil, agentConfig.ProviderConfig{}, err
	}
	pc.Model = selected.Model

	selection := providerSelection{
		Route:             routeKey,
		Provider:          selected.Provider,
		RequestedModel:    routeKey,
		RequestedModelRef: routeModelRef,
		ResolvedModel:     pc.Model,
		NoStream:          true,
	}
	if resolved != nil {
		selection.ResolvedModelRef = resolved.CanonicalID
		selection.ReasoningDefault = fizeau.Reasoning(resolved.SurfacePolicy.ReasoningDefault)
		if resolved.ConcreteModel != "" {
			selection.ResolvedModel = resolved.ConcreteModel
		}
	} else if routeModelRef != "" {
		selection.ResolvedModelRef = routeKey
	}
	if selection.ReasoningDefault == "" && routeModelRef != "" {
		if catalogResolved, err := resolveCanonicalModelRef(cfg, routeModelRef, allowDeprecated); err == nil {
			selection.ReasoningDefault = fizeau.Reasoning(catalogResolved.SurfacePolicy.ReasoningDefault)
			if selection.ResolvedModelRef == "" || selection.ResolvedModelRef == routeKey {
				selection.ResolvedModelRef = catalogResolved.CanonicalID
			}
		}
	}
	return selection, p, pc, nil
}

func resolveCanonicalModelRef(cfg *agentConfig.Config, ref string, allowDeprecated bool) (*modelcatalog.ResolvedTarget, error) {
	catalog, err := cfg.LoadModelCatalog()
	if err != nil {
		return nil, err
	}
	surfaces := []modelcatalog.Surface{
		modelcatalog.SurfaceAgentOpenAI,
		modelcatalog.SurfaceAgentAnthropic,
	}
	var lastErr error
	for _, surface := range surfaces {
		resolved, err := catalog.Resolve(ref, modelcatalog.ResolveOptions{
			Surface:         surface,
			AllowDeprecated: allowDeprecated,
		})
		if err == nil {
			return &resolved, nil
		}
		var missingSurfaceErr *modelcatalog.MissingSurfaceError
		if errors.As(err, &missingSurfaceErr) {
			lastErr = err
			continue
		}
		return nil, err
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, fmt.Errorf("config: cannot resolve model reference %q", ref)
}

func selectBackendProviderIndex(strategy string, counter, n int) int {
	if n <= 0 {
		return 0
	}
	if strategy == "round-robin" {
		return counter % n
	}
	return 0
}

